-- public.register_push_device / revoke_push_device
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
insert into auth.users (id, email) values ('11111111-1111-1111-1111-111111111111','u1@example.test'),('22222222-2222-2222-2222-222222222222','u2@example.test');
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select public.register_push_device('ios','ExponentPushToken[aaaaaaaaaaaa]',null,null) $$, '42501', null, 'anonymous cannot register');
reset role; select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.register_push_device('ios','ExponentPushToken[aaaaaaaaaaaa]',null,'My iPhone') $$, 'register an Expo token');
select is((select count(*)::int from public.push_devices where revoked_at is null), 1, 'device stored');
select lives_ok($$ select public.register_push_device('ios','ExponentPushToken[aaaaaaaaaaaa]',null,null) $$, 'registering again is idempotent');
select is((select count(*)::int from public.push_devices), 1, 'still one row');
select is((select device_label from public.push_devices), 'My iPhone', 'label kept');
select throws_ok($$ select public.register_push_device('ios','not-a-token-at-all',null,null) $$, '23514', 'invalid_expo_token', 'bad Expo token refused');
select throws_ok($$ select public.register_push_device('web','http://insecure.example/x','{"p256dh":"a","auth":"b"}'::jsonb,null) $$, '23514', 'invalid_web_subscription', 'web endpoint must be https');
select throws_ok($$ select public.register_push_device('web','https://push.example.com/abc123',null,null) $$, '23514', 'invalid_web_subscription', 'web needs a subscription');
select lives_ok($$ select public.register_push_device('web','https://push.example.com/abc123','{"p256dh":"a","auth":"b"}'::jsonb,null) $$, 'register a web push subscription');
select throws_ok($$ select public.register_push_device('tv','ExponentPushToken[aaaaaaaaaaaa]',null,null) $$, '23514', 'invalid_platform', 'unknown platform refused');
select lives_ok($$ select public.revoke_push_device(p_token => 'ExponentPushToken[aaaaaaaaaaaa]') $$, 'revoke by token (logout)');
select is((select count(*)::int from public.push_devices where revoked_at is null), 1, 'only the web device remains active');
reset role; select set_config('request.jwt.claims', '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select lives_ok($$ select public.register_push_device('ios','ExponentPushToken[aaaaaaaaaaaa]',null,null) $$, 'a second account takes over a shared device token');
select is((select count(*)::int from public.push_devices), 1, 'the device now belongs to the second account');
reset role; select set_config('request.jwt.claims', '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.push_devices where platform='ios'), 0, 'and the first account no longer has it');
reset role;
reset role;
select * from finish();
rollback;
